action.code:
// XOR the tag
a->tag ^= b->tag;

// XOR the pair
a->pair[0] ^= b->pair[0];
a->pair[1] ^= b->pair[1];

// XOR the mask
a->mask ^= b->mask;

// XOR the tag size
a->tag_size ^= b->tag_size;

// XOR the data size
a->data_size ^= b->data_size;

// XOR the data
for (int i = 0; i < sizeof(a->data); i++) {
    a->data[i] ^= b->data[i];
}

